var e={"tour.step":`Step {n} of {total}`,"tour.next":`Next`,"tour.back":`Back`,"tour.finish":`Finish`,"tour.skip":`Skip the tour`,"tour.close":`Close`,"tour.nav.title":`Navigation`,"tour.nav.body":`Everything lives in this sidebar: dashboard, sessions, files, tasks and settings. Tip: press G then a letter to jump (G S = Sessions).`,"tour.nav.bodyMobile":`⊞ at the top right opens every page: dashboard, sessions, files, tasks, settings. ☰ at the top left opens the list of the page you are on (your sessions on Sessions).`,"tour.tree.title":`Projects, topics, sessions`,"tour.tree.body":`Your work is organised in projects, each split into topics. A topic is a folder Harness works in, with its own memory; every conversation in it is a session.`,"tour.new.title":`Start a session`,"tour.new.body":`Opens a new conversation in the current topic. Shortcut: Alt+N.`,"tour.new.bodyMobile":`Opens a new conversation in the topic of the session on screen.`,"tour.composer.title":`Talk to Harness`,"tour.composer.body":`Type your request, attach files, or use the mic to dictate. Enter sends; new messages queue up while Harness is working.`,"tour.palette.title":`Find anything`,"tour.palette.body":`Press ⌘K / Ctrl+K to search files, sessions, topics, settings and actions. The fastest way around.`,"tour.palette.bodyMobile":`Search files, sessions, topics, settings and actions from here.`,"tour.tasks.title":`Tasks`,"tour.tasks.body":`Tasks is your board of things to do, that Harness can read and update too.`,"tour.settings.title":`Settings`,"tour.settings.body":`Crons (scheduled jobs: a nightly report, a backup), Telegram to chat from your phone, voice messages and the backup of your memory to GitHub: it all lives here.`,"tour.health.title":`Server health`,"tour.health.body":`This dot turns orange or red when something needs attention: disk, memory, a failed cron, a stopped service. Click it for details.`,"tour.health.bodyMobile":`Updates, server health and your Claude plan, at a glance. A dot on ⊞ tells you when something needs your attention.`,"tour.final.title":`You're all set`,"tour.final.body":`Learn by doing: the interactive tutorial walks you through your first real session with Harness. Replay this tour anytime from Settings -> General.`,"tour.final.bodyNoTutorial":`The documentation covers every page in detail. Replay this tour anytime from Settings -> General.`,"tour.final.tutorial":`Start the interactive tutorial`,"tour.final.docs":`Open the docs`};export{e as default};